css:
*{box-sizing:border-box}
body{margin:0;background:#0A0A0D;color:#F2F2EC;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;line-height:1.45;-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit;text-decoration:none}
.mono{font-family:ui-monospace,'SF Mono',Menlo,Consolas,monospace}
.wrap{max-width:1240px;margin:0 auto;padding:clamp(40px,7vw,90px) clamp(20px,5vw,64px)}
.eyebrow{font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:#8A8A96;display:flex;align-items:center;gap:16px;margin-bottom:clamp(22px,3vw,40px)}
.eyebrow .line{height:1px;flex:1;background:#26262E}
.eyebrow .accent{color:var(--jj-accent)}
.hero h1{font-weight:800;line-height:.84;letter-spacing:-.045em;text-transform:uppercase;font-size:clamp(52px,14vw,190px);margin:0;position:relative;display:inline-block;word-break:break-word}
.hero h1::after{content:'';position:absolute;left:0;bottom:.08em;width:100%;height:.1em;background:var(--jj-accent)}
.block{margin-top:clamp(56px,9vw,120px)}
.sec-head{display:flex;align-items:baseline;justify-content:space-between;gap:20px;flex-wrap:wrap;border-top:1px solid #26262E;padding-top:22px;margin-bottom:clamp(28px,4vw,50px)}
.sec-head h2{font-weight:800;letter-spacing:-.03em;text-transform:uppercase;font-size:clamp(24px,4vw,50px);line-height:.95;margin:0}
.sec-head .tag{font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#8A8A96}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:clamp(20px,2.4vw,30px);counter-reset:card}
.card{position:relative;display:block;border:1px solid #26262E;background:#111116;overflow:hidden;counter-increment:card;transition:border-color .35s ease,transform .35s cubic-bezier(.16,1,.3,1)}
.card:hover{border-color:var(--jj-accent);transform:translateY(-6px)}
.card .cover{aspect-ratio:16/10;background:radial-gradient(120% 90% at 18% 12%,color-mix(in srgb,var(--jj-accent) 60%,transparent),transparent 55%),radial-gradient(120% 90% at 85% 40%,rgba(52,120,255,.35),transparent 55%),conic-gradient(from 200deg at 60% 80%,#12122a,#201038,#2a1030,#12122a);transition:transform .6s cubic-bezier(.16,1,.3,1)}
.card:hover .cover{transform:scale(1.05)}
.card .idx{position:absolute;top:14px;left:16px;z-index:2;font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:12px;letter-spacing:.2em;color:#F2F2EC;mix-blend-mode:difference}
.card .idx::before{content:counter(card,decimal-leading-zero)}
.card .arrow{position:absolute;top:12px;right:14px;z-index:2;width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(242,242,236,.55);border-radius:50%;font-size:15px;color:#F2F2EC;transition:background .3s ease,color .3s ease,border-color .3s ease,transform .3s ease}
.card:hover .arrow{background:var(--jj-accent);border-color:var(--jj-accent);color:#0A0A0D;transform:rotate(-45deg)}
.card-meta{padding:20px 22px 24px}
.card-meta h3{font-weight:800;letter-spacing:-.02em;text-transform:uppercase;font-size:clamp(20px,2.6vw,32px);line-height:.98;margin:0}
.empty{color:#8A8A96;font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:13px;letter-spacing:.05em}
.panel{border:1px solid #26262E;background:#111116;border-radius:2px;padding:clamp(20px,3vw,34px)}
.entry .back{display:inline-block;font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#8A8A96;margin-bottom:clamp(22px,4vw,44px);transition:color .25s ease}
.entry .back:hover{color:var(--jj-accent)}
.entry-title{font-weight:800;letter-spacing:-.04em;text-transform:uppercase;font-size:clamp(40px,9vw,120px);line-height:.86;margin:0 0 clamp(28px,5vw,56px);max-width:16ch}
.fields{max-width:760px}
.fld{margin:0 0 clamp(20px,3vw,34px);border-top:1px solid #26262E;padding-top:18px}
.fld-label{font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:#8A8A96;margin-bottom:10px}
.fld a{color:var(--jj-accent);border-bottom:1px solid transparent;transition:border-color .2s}
.fld a:hover{border-color:var(--jj-accent)}
.rt{font-size:clamp(16px,1.4vw,18px);line-height:1.65;color:#D5D5DC}
.rt h1,.rt h2,.rt h3{font-weight:800;letter-spacing:-.02em;text-transform:uppercase;color:#F2F2EC;line-height:1;margin:1.4em 0 .5em}
.rt a{color:var(--jj-accent)}
.rt img,.img{max-width:100%;border-radius:2px}.img{max-height:420px}
.rt code{font-family:ui-monospace,'SF Mono',Menlo,monospace;background:#111116;border:1px solid #26262E;padding:1px 6px;border-radius:3px;font-size:.9em}
.rt blockquote{border-left:3px solid var(--jj-accent);margin:1.2em 0;padding:.2em 0 .2em 18px;color:#B8B8C2}
.swatch{display:inline-block;width:16px;height:16px;border-radius:3px;vertical-align:middle;border:1px solid #26262E}
ul{padding-left:20px}li{margin:4px 0}
footer{border-top:1px solid #26262E;margin-top:clamp(60px,9vw,110px);padding:24px clamp(20px,5vw,64px);color:#8A8A96;font-family:ui-monospace,'SF Mono',Menlo,monospace;font-size:11px;letter-spacing:.16em;text-transform:uppercase;text-align:center}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
